+void Handler::setAutoconnect(const QString &connection, bool autoconnect)
+{
+    setAutoconnectInternal(connection, autoconnect);
+}
+
+QCoro::Task<> Handler::setAutoconnectInternal(const QString &connection, bool autoconnect)
+{
+    NetworkManager::Connection::Ptr con = NetworkManager::findConnection(connection);
+
+    if (!con || con->uuid().isEmpty()) {
+        qCWarning(PLASMA_NM_LIBS_LOG) << "Not possible to change autoconnect of connection " << connection;
+        co_return;
+    }
+
+    NetworkManager::ConnectionSettings::Ptr settings = con->settings();
+    if (settings->autoconnect() == autoconnect) {
+        co_return;
+    }
+    settings->setAutoconnect(autoconnect);
+
+    QPointer<Handler> thisGuard(this);
+    QDBusReply<void> reply = co_await con->update(settings->toMap());
+    if (!thisGuard) {
+        co_return;
+    }
+
+    if (!reply.isValid()) {
+        KNotification *notification = new KNotification(QStringLiteral("FailedToUpdateConnection"), KNotification::CloseOnTimeout, this);
+        notification->setTitle(i18nc("@title", "Failed to update connection %1", con->name()));
+        notification->setComponentName(QStringLiteral("networkmanagement"));
+        notification->setText(reply.error().message());
+        notification->setIconName(QStringLiteral("dialog-warning"));
+        notification->sendEvent();
+    }
+}
+
 QCoro::Task<> Handler::updateConnection(NetworkManager::Connection::Ptr connection, const NMVariantMapMap &map)
